const when=t=>new Date(t).toLocaleString([],{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});
function ev(text,k){const e={at:Date.now(),by:nameOf(real)+(cur!=real?' (acting as '+nameOf(cur)+')':''),text,tid:k?k.id:0};log.unshift(e);if(k)k.lc={at:e.at,by:e.by,text:e.text,tid:e.tid}}
