function vHist(){return `<h2>Change history</h2><p class="mut">Every change anyone makes, newest first.</p><section>${log.slice(0,200).map(e=>`<div class="row"><div>${esc(e.text)}<br><span class="mut">${esc(e.by)}</span></div><span class="mut">${when(e.at)}</span></div>`).join('')||'<p>Nothing yet.</p>'}</section>`}
