function pie(c){const tot=c.done+c.progress+c.todo+c.blocked;if(!tot)return '<svg viewBox="0 0 120 120" width="150"><circle cx="60" cy="60" r="50" fill="none" stroke="#8a94a6" stroke-width="2"/><text x="60" y="64" text-anchor="middle" font-size="12" fill="currentColor">No tasks</text></svg>';
let a=-Math.PI/2,o='';Object.keys(SL).forEach(x=>{const q=c[x]/tot;if(!q)return;if(q>.9999){o+=`<circle cx="60" cy="60" r="55" fill="${SC[x]}"><title>${SL[x]}: ${c[x]}</title></circle>`;return}const b=a+q*2*Math.PI;o+=`<path d="M60 60L${60+55*Math.cos(a)} ${60+55*Math.sin(a)}A55 55 0 ${q>.5?1:0} 1 ${60+55*Math.cos(b)} ${60+55*Math.sin(b)}Z" fill="${SC[x]}"><title>${SL[x]}: ${c[x]}</title></path>`;a=b});return `<svg viewBox="0 0 120 120" width="170" role="img">${o}</svg>`}
function bars(t){const cols=people.filter(p=>p.t==t&&['lead','member'].includes(p.r)).map(p=>({n:p.n,c:cnt(tasks.filter(k=>k.t==t&&k.who==p.id))})),un=tasks.filter(k=>k.t==t&&!k.who);if(un.length)cols.push({n:'Unassigned',c:cnt(un)});
const tot=o=>o.c.done+o.c.progress+o.c.todo+o.c.blocked,mx=Math.max(1,...cols.map(tot)),st=Math.ceil(mx/6),W=Math.max(320,cols.length*90+60);let g='';
for(let i=0;i<=mx;i+=st){const y=210-i*180/mx;g+=`<line x1="40" x2="${W}" y1="${y}" y2="${y}" stroke="currentColor" opacity=".15"/><text x="34" y="${y+4}" text-anchor="end" font-size="11" fill="currentColor">${i}</text>`}
cols.forEach((o,i)=>{let y=210;const x=60+i*90,w=o.n.split(' ');Object.keys(SL).forEach(s=>{const h=o.c[s]*180/mx;if(!h)return;y-=h;g+=`<rect x="${x}" y="${y}" width="44" height="${h}" fill="${SC[s]}"><title>${esc(o.n)}: ${SL[s]} ${o.c[s]}</title></rect>`});g+=`<text x="${x+22}" y="228" text-anchor="middle" font-size="11" fill="currentColor">${esc(w[0])}</text><text x="${x+22}" y="242" text-anchor="middle" font-size="11" fill="currentColor">${esc(w.slice(1).join(' '))}</text>`});
return `<div class="tw"><svg viewBox="0 0 ${W} 250" width="${W}" role="img">${g}</svg></div>`}
function prio(teams){const l=tasks.filter(k=>teams.includes(k.t)&&k.s!='done').map(k=>{const r=[];if(k.s=='blocked')r.push(['Blocked: needs help','b']);if(k.due){const n=Math.round((new Date(k.due+'T12:00:00')-new Date(TODAY+'T12:00:00'))/864e5);if(n<0)r.push(['Overdue by '+(-n)+' day(s)','d']);else if(n<=7)r.push([n?'Due in '+n+' day(s)':'Due today','d'])}const q=(Date.now()-k.lc.at)/864e5;if(q>=dx)r.push(['No change in '+Math.floor(q)+' day(s)','s']);return{k,r}}).filter(o=>o.r.length).sort((a,b)=>'bds'.indexOf(a.r[0][1])-'bds'.indexOf(b.r[0][1]));
return l.map(o=>`<div class="row"><div><b>${esc(o.k.x)}</b> <span class="mut">${o.k.t}, ${o.k.who?esc(nameOf(o.k.who)):'not assigned'}</span><br>${stat(o.k)} ${o.r.map(x=>`<span class="b ${x[1]=='b'?'s-blocked':x[1]=='d'?'s-progress':''}">${x[0]}</span>`).join(' ')}${helpTxt(o.k)}${lastTxt(o.k)}</div></div>`).join('')||'<p>Nothing needs attention right now.</p>'}
function vRec(){return `<h2>Records for Teams</h2><section><p>Download one Excel file for a single date, to keep in your Teams channel under Files. Every value has its own cell, and each kind of information has its own sheet.</p><div class="row"><label>Date <input type="date" id="expd" value="${expd||TODAY}"></label><button class="sel" data-exp="day">Download Excel for this date</button></div><div class="row"><span class="mut">Or get a separate Excel file for every date that has attendance:</span><button data-exp="all">Download every date</button></div><p class="mut">Sheets in each file: Summary, Attendance, Task updates, All tasks, Change history, Mentors, Events and Parts requests. Attendance, Task updates, Change history, Mentors and Events are for the chosen date. All tasks and Parts requests show the current state when you download.</p></section><section><h3>Attendance sheet</h3><p>A simple, colorful Excel file just for attendance. Every full name has its own cell, with green for here and red for absent. A second sheet shows every date side by side with each person's attendance rate.</p><div class="row"><label>Date <input type="date" id="expa" value="${expd||TODAY}"></label><button class="sel" data-exp="att">Download attendance Excel</button></div></section>`}
