if(dpage=='Competition')return `<h2>Directors view: Competition</h2>${ok.length>1?`<div class="seg">${ok.map(p=>`<button class="${p==dpage?'sel':''}" data-dp="${p}">${p}</button>`).join('')}</div>`:''}`+vComp().replace(/^<h2>Competition<\/h2>/,'');
const teams=P2[dpage],kind=dpage=='Engineering'?'eng':'comm',tk=tasks.filter(k=>teams.includes(k.t)),open=tk.filter(k=>k.s!='done'),dayN=k=>k.due?Math.round((new Date(k.due+'T12:00:00')-new Date(TODAY+'T12:00:00'))/864e5):99,pend=reqs.filter(r=>r.kind==kind&&r.status=='pending'),seeP=canApprove(m,kind)||m.r=='core',tile=(n,l,c,ls)=>tileB('dir'+dpage,n,l,c,ls);
