const unread=()=>notes.filter(n=>n.to==cur&&!n.read&&!closed(n)).length;
const helpBanner=()=>unread()?`<p><span class="b s-blocked">${unread()} notification${unread()>1?'s':''} waiting for you. Open the Dashboard.</span></p>`:'';
