function noteRow(n){const k=tasks.find(k=>k.id==n.tid),cl=closed(n),h=k&&(k.help||[]).find(h=>h.id==cur);return `<div class="dbitem" style="align-items:flex-start"><div><b>${esc(n.text)}</b>${n.note?`<div class="sub" style="margin:0">"${esc(n.note)}"</div>`:''}<div class="sub" style="margin:0">${ago(n.at)}${k?'. '+esc(k.x):''}</div></div><div class="dbact">${n.kind=='req'?reqOpen():''}${n.kind=='help'?(cl?'<span class="b">No longer blocked</span>':`${h&&h.r!='asked'?`<span class="b">${h.r=='yes'?'You will help':'You cannot help'}</span>`:''}<button class="sel" data-hans="${n.id}:yes">I will help</button><button data-hans="${n.id}:no">Cannot help</button>`):''}${!n.read?`<button data-nread="${n.id}">Mark read</button>`:''}</div></div>`}
function nextMeets(n){const out=[],d0=new Date(TODAY+'T12:00:00');for(let i=0;i<60&&out.length<n;i++){const d=new Date(d0);d.setDate(d.getDate()+i);const k=d.toLocaleDateString('en-CA'),s=st(k);if(s=='g'||s=='y')out.push(k)}return out}
function dbBars(){const T5=['Mechanical','Electrical','Programming','Business','Imagery'],rows=T5.map(t=>({t,c:cnt(tasks.filter(k=>k.t==t))})),mx=Math.max(4,...rows.map(r=>r.c.done+r.c.progress+r.c.todo+r.c.blocked)),W=560,bw=52,gap=(W-60-5*bw)/4;let g='';
for(let i=0;i<=4;i++){const y=170-i*37.5;g+=`<line x1="40" x2="${W}" y1="${y}" y2="${y}" stroke="currentColor" opacity=".12"/><text x="34" y="${y+4}" text-anchor="end" font-size="11" fill="currentColor" opacity=".7">${Math.round(mx*i/4)}</text>`}
rows.forEach((r,i)=>{let y=170;const x=50+i*(bw+gap);Object.keys(SL).forEach(s=>{const h=r.c[s]*150/mx;if(!h)return;y-=h;g+=`<rect x="${x}" y="${y}" width="${bw}" height="${h}" rx="3" fill="${DC[s]}"><title>${r.t}: ${SL[s]} ${r.c[s]}</title></rect>`});g+=`<text x="${x+bw/2}" y="190" text-anchor="middle" font-size="12" fill="currentColor">${r.t}</text>`});
return `<svg viewBox="0 0 ${W} 200" width="100%" role="img" aria-label="Tasks by subteam">${g}</svg><div class="dbleg">${Object.keys(SL).map(s=>`<span><i class="dot" style="background:${DC[s]}"></i>${SL[s]}</span>`).join('')}</div>`}
function dbDonut(c){const tot=c.done+c.progress+c.todo+c.blocked,R=54,C=2*Math.PI*R;let off=0,s='';
if(!tot)return '<svg viewBox="0 0 160 160" width="170"><circle cx="80" cy="80" r="54" fill="none" stroke="#b9c4d3" stroke-width="24"/><text x="80" y="86" text-anchor="middle" font-size="14" fill="currentColor">No tasks</text></svg>';
Object.keys(SL).forEach(k=>{const len=c[k]/tot*C;if(len>0){s+=`<circle cx="80" cy="80" r="${R}" fill="none" stroke="${DC[k]}" stroke-width="24" stroke-dasharray="${len} ${C-len}" stroke-dashoffset="${-off}" transform="rotate(-90 80 80)"><title>${SL[k]}: ${c[k]}</title></circle>`;off+=len}});
return `<svg viewBox="0 0 160 160" width="170" role="img" aria-label="${Math.round(c.done/tot*100)} percent of tasks are done">${s}<text x="80" y="84" text-anchor="middle" font-size="30" font-weight="700" fill="currentColor">${Math.round(c.done/tot*100)}%</text><text x="80" y="104" text-anchor="middle" font-size="12" fill="currentColor" opacity=".7">done</text></svg>`}
function dbArea(w){const days=[],now=new Date(TODAY+'T12:00:00');for(let i=13;i>=0;i--){const d=new Date(now);d.setDate(d.getDate()-i);days.push(d.toLocaleDateString('en-CA'))}
const v=days.map(d=>w.filter(x=>dstr0(x.at)==d).length),mx=Math.max(3,...v),W=560,X=i=>40+i*(W-60)/13,Y=n=>140-n*110/mx,ln=v.map((n,i)=>(i?'L':'M')+X(i)+' '+Y(n)).join(' ');let g='';
for(let i=0;i<=3;i++){const y=140-i*110/3;g+=`<line x1="40" x2="${W}" y1="${y}" y2="${y}" stroke="currentColor" opacity=".12"/><text x="34" y="${y+4}" text-anchor="end" font-size="11" fill="currentColor" opacity=".7">${Math.round(mx*i/3)}</text>`}
return `<svg viewBox="0 0 ${W} 170" width="100%" role="img" aria-label="Accomplishments per day, last 14 days">${g}<path d="${ln} L${X(13)} 140 L${X(0)} 140 Z" fill="#f5a623" opacity=".4"/><path d="${ln}" fill="none" stroke="#173a63" stroke-width="2.5" stroke-linejoin="round"/>${v.map((n,i)=>`<circle cx="${X(i)}" cy="${Y(n)}" r="3.5" fill="#173a63"><title>${fd(days[i])}: ${n}</title></circle>`).join('')}${[0,6,13].map(i=>`<text x="${X(i)}" y="160" text-anchor="middle" font-size="11" fill="currentColor" opacity=".8">${fd(days[i])}</text>`).join('')}</svg>`}
function dbCal(){const n=new Date(TODAY+'T12:00:00'),y=n.getFullYear(),mo=n.getMonth(),dim=new Date(y,mo+1,0).getDate(),first=new Date(y,mo,1).getDay();let c='';for(let i=0;i<first;i++)c+='<span></span>';
for(let d=1;d<=dim;d++){const k=k2(y,mo,d),s=st(k);c+=`<button class="dbday ${s}${k==TODAY?' today':''}" data-gocal="${k}" title="${s=='g'?'Meeting':s=='y'?'Still being decided':s=='r'?'No meeting':'Open this day'}">${d}</button>`}
return `<div class="sub">${n.toLocaleDateString('en-US',{month:'long',year:'numeric'})}</div><div class="dbcal"><b>S</b><b>M</b><b>T</b><b>W</b><b>T</b><b>F</b><b>S</b>${c}</div><div class="dbleg"><span><i class="dot" style="background:rgba(27,122,74,.5)"></i>Meeting</span><span><i class="dot" style="background:rgba(245,166,35,.6)"></i>Deciding</span><span><i class="dot" style="background:rgba(217,48,37,.5)"></i>None</span></div>`}
const orderedBox=()=>{const o=reqs.filter(r=>r.status=='ordered');return `<section><h3>Already ordered</h3>${o.map(r=>`<div class="row"><span>${esc(r.item)}</span><span class="b s-done">Ordered</span></div>`).join('')||'<p class="mut">Nothing has been ordered yet.</p>'}</section>`};
function vOrders2(){return vOrders2b()+treasExtra()}
function treasExtra(){const m=me();if(m.ti!='Treasurer')return '';const pend=reqs.filter(r=>r.status=='pending'),no=reqs.filter(r=>['rejected','withdrawn'].includes(r.status));return `<h3>Waiting for director approval</h3><p class="mut">You can follow every request from the moment it is sent until it is ordered.</p>${pend.map(r=>rcard(r,`<p><span class="b">${RS[r.status]}</span></p>`)).join('')||'<p class="mut">Nothing waiting.</p>'}<h3>Not approved or withdrawn</h3>${no.map(r=>rcard(r,`<p><span class="b">${RS[r.status]}</span></p>`)).join('')||'<p class="mut">None.</p>'}`}
